INSERT INTO projects (id,gallery_key,category,sort,title_fr,title_en,title_de,desc_fr,desc_en,desc_de) VALUES ('voiries-kinshasa','voiriesKinshasa','travaux-publics',1,'Voiries et assainissement à Kinshasa','Roads and drainage in Kinshasa','Straßenbau und Entwässerung in Kinshasa','Un projet de construction de 12 km de voiries répartis sur six axes, avec système d’assainissement.','A project to construct 12 km of roads across six routes, with a drainage system.','Ein Projekt zum Bau von 12 km Straßen auf sechs Strecken mit einem Entwässerungssystem.');
INSERT INTO projects (id,gallery_key,category,sort,title_fr,title_en,title_de,desc_fr,desc_en,desc_de) VALUES ('construction-projet-01','construction01','construction-neuve',2,'Bâtiment R+1 à Kinshasa','Two-storey building in Kinshasa','Zweigeschossiges Gebäude in Kinshasa','Un projet de construction présenté à travers ses étapes, dans l’ordre des dates disponibles des photographies.','A construction project presented by stage, following the available photo dates.','Ein Bauprojekt in seinen Phasen, geordnet nach den verfügbaren Fotodaten.');
INSERT INTO projects (id,gallery_key,category,sort,title_fr,title_en,title_de,desc_fr,desc_en,desc_de) VALUES ('ecole-cite-du-savoir','ecoleCite','construction-neuve',3,'École Cité du savoir','Cité du savoir School','Schule Cité du savoir','Construction d’une école R+1 au Bon Marché, à Kinshasa, en 2024. Le bâtiment comprend également des bureaux administratifs et une bibliothèque.','Construction of a two-storey school in Bon Marché, Kinshasa, in 2024. The building also includes administrative offices and a library.','Bau einer zweigeschossigen Schule in Bon Marché, Kinshasa, im Jahr 2024. Das Gebäude umfasst außerdem Verwaltungsbüros und eine Bibliothek.');
