INSERT INTO projects (id,gallery_key,category,sort,title_fr,title_en,title_de,desc_fr,desc_en,desc_de) VALUES ('future-tower','futureTower','renovation-amenagement',5,'Future Tower','Future Tower','Future Tower','Rénovation de 6 appartements dans l’immeuble Future Tower, à Kinshasa. Le projet comprend les travaux de peinture, de carrelage, de MEP et de climatisation, ainsi que l’installation des portes et fenêtres.','Renovation of 6 apartments in Future Tower, Kinshasa. The project includes painting, tiling, MEP, air conditioning and installation of doors and windows.','Renovierung von 6 Wohnungen im Future Tower in Kinshasa. Das Projekt umfasst Malerarbeiten, Fliesen, Gebäudetechnik, Klimatisierung sowie den Einbau von Türen und Fenstern.');
INSERT INTO projects (id,gallery_key,category,sort,title_fr,title_en,title_de,desc_fr,desc_en,desc_de) VALUES ('projet-pont-ngaby','pontNgaby','renovation-amenagement',6,'Aménagement de boutiques à Pont Ngaby','Shop fit-out in Pont Ngaby','Ausbau von Geschäftslokalen in Pont Ngaby','Aménagement de 8 boutiques commerciales sur une surface de 800 m² à Pont Ngaby, Kinshasa, en 2024.','Fit-out of 8 commercial shops across 800 m² in Pont Ngaby, Kinshasa, in 2024.','Ausbau von 8 Geschäftslokalen auf einer Fläche von 800 m² in Pont Ngaby, Kinshasa, im Jahr 2024.');
